description:
Write a pure function `reduce(state, action)` for a to-do list that never changes `state` and returns a new state. The state is `{ todos: [{ id, text, done }], nextId }`. Actions:

- `{ type: "add", text }` adds `{ id: nextId, text, done: false }` at the end and increases `nextId`; text is trimmed, and empty text changes nothing (return the same state object);
- `{ type: "toggle", id }` flips `done` of that to-do;
- `{ type: "rename", id, text }` changes its text (trimmed; empty text changes nothing);
- `{ type: "clearDone" }` removes finished to-dos;
- `{ type: "move", id, to }` moves a to-do to index `to` (clamped to the list);
- an unknown action or id returns the same state object unchanged.

Then write `replay(actions, initial)` that applies a list of actions with `reduce`.

starter.solution.js:
const initial = { todos: [], nextId: 1 };

function reduce(state, action) {
  if (action.type === "add") state.todos.push({ id: state.nextId++, text: action.text, done: false });
  return state;
}

function replay(actions, start = initial) {
  return actions.reduce(reduce, start);
}

solution.solution.js:
const initial = { todos: [], nextId: 1 };

function reduce(state, action) {
  const index = state.todos.findIndex(t => t.id === action.id);
  switch (action.type) {
    case "add": {
      const text = String(action.text || "").trim();
      if (!text) return state;
      return { todos: [...state.todos, { id: state.nextId, text, done: false }], nextId: state.nextId + 1 };
    }
    case "toggle":
      if (index < 0) return state;
      return { ...state, todos: state.todos.with(index, { ...state.todos[index], done: !state.todos[index].done }) };
    case "rename": {
      const text = String(action.text || "").trim();
      if (index < 0 || !text) return state;
      return { ...state, todos: state.todos.with(index, { ...state.todos[index], text }) };
    }
    case "clearDone":
      if (!state.todos.some(t => t.done)) return state;
      return { ...state, todos: state.todos.filter(t => !t.done) };
    case "move": {
      if (index < 0) return state;
      const to = Math.max(0, Math.min(action.to, state.todos.length - 1));
      const without = state.todos.toSpliced(index, 1);
      return { ...state, todos: without.toSpliced(to, 0, state.todos[index]) };
    }
    default:
      return state;
  }
}

function replay(actions, start = initial) {
  return actions.reduce(reduce, start);
}

unitTests:
function frozen(value) {
  if (value && typeof value === "object") {
    Object.freeze(value);
    Object.values(value).forEach(frozen);
  }
  return value;
}

test("add and toggle", () => {
  const s = replay([{ type: "add", text: " milk " }, { type: "add", text: "eggs" }, { type: "toggle", id: 1 }]);
  checkEq(s, { todos: [{ id: 1, text: "milk", done: true }, { id: 2, text: "eggs", done: false }], nextId: 3 });
});

test("the old state is never changed", () => {
  const before = frozen(replay([{ type: "add", text: "a" }, { type: "add", text: "b" }]));
  const copy = JSON.stringify(before);
  replay([{ type: "toggle", id: 1 }, { type: "rename", id: 2, text: "B" }, { type: "move", id: 2, to: 0 }, { type: "clearDone" }], before);
  checkEq(JSON.stringify(before), copy);
});

test("rename, move and clear", () => {
  const s = replay([
    { type: "add", text: "a" }, { type: "add", text: "b" }, { type: "add", text: "c" },
    { type: "rename", id: 3, text: " C " }, { type: "move", id: 3, to: 0 }, { type: "toggle", id: 1 }, { type: "clearDone" },
  ]);
  checkEq(s.todos.map(t => t.text), ["C", "b"]);
});

test("move clamps the index", () => {
  const s = replay([{ type: "add", text: "a" }, { type: "add", text: "b" }, { type: "move", id: 1, to: 99 }]);
  checkEq(s.todos.map(t => t.id), [2, 1]);
});

test("nothing to do returns the same object", () => {
  const s = replay([{ type: "add", text: "a" }]);
  check(reduce(s, { type: "add", text: "  " }) === s);
  check(reduce(s, { type: "toggle", id: 42 }) === s);
  check(reduce(s, { type: "fly" }) === s);
  check(reduce(s, { type: "clearDone" }) === s);
});

